{
  "kc_id": "KC_EVAL_SAMP_003",
  "canonical_name": "k-Fold Cross Validation",
  "definition": {
    "status": "grounded",
    "text": "Cross-validation is a model evaluation method that aims to make effective use of all labeled instances in a dataset for both training and testing.",
    "supporting_evidence_ids": [
      "E5"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "text": "Cross-validation is used for model evaluation and model selection, including hyper-parameter selection. In a k-fold framework for hyper-parameter selection, it allows for obtaining the best hyper-parameter value and the final classification model by making effective use of every data instance in the training set.",
    "supporting_evidence_ids": [
      "E2",
      "E4",
      "E7"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_CLF_DT_006",
  "canonical_name": "Information Gain",
  "definition": {
    "status": "grounded",
    "text": "The information gain from a feature A, IG(A), is defined as the difference between the prior uncertainty and the expected posterior uncertainty using A.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "text": "Irrelevant attributes typically show poor information gain, allowing rule-based classifiers to avoid them if other relevant attributes show better information gain; however, in complex problems with interacting attributes that individually show poor information gain, an irrelevant attribute may be accidentally favored over a relevant one by random chance.",
    "supporting_evidence_ids": [
      "E6",
      "E7"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_CLU_SIM_003",
  "canonical_name": "Euclidean Distance",
  "definition": {
    "status": "abstained",
    "text": "",
    "supporting_evidence_ids": [],
    "abstention_reason": "The definition_lane contains mentions of Euclidean distance in relation to Mahalanobis distance and cohesion measures, but does not provide a direct definition of Euclidean distance itself."
  },
  "scope": {
    "status": "grounded",
    "text": "Euclidean distance can be used to measure the distance between entities based on attributes; however, if attributes have different scales (different ranges of values) and are not standardized, the distance calculation will be dominated by the attribute with the larger range.",
    "supporting_evidence_ids": [
      "E4"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_CLU_SIM_007",
  "canonical_name": "Jaccard Coefficient",
  "definition": {
    "status": "abstained",
    "text": "",
    "supporting_evidence_ids": [],
    "abstention_reason": "The definition_lane contains information about extending the coefficient to more than two variables, but does not provide a direct definition of the Jaccard Coefficient itself."
  },
  "scope": {
    "status": "grounded",
    "text": "The Jaccard coefficient is frequently used to handle objects consisting of asymmetric binary attributes and is the form to which the extended Jaccard coefficient reduces in the case of binary attributes.",
    "supporting_evidence_ids": [
      "E5",
      "E3"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_CLU_EVAL_002",
  "canonical_name": "SSE (Cluster Quality)",
  "definition": {
    "status": "grounded",
    "text": "Also known as scatter, the sum of the squared error (SSE) is an objective function used to measure the quality of a clustering; it is calculated by computing the error of each data point (its Euclidean distance to the closest centroid) and then computing the total sum of the squared errors.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "text": "In the context of K-means, the centroid that minimizes the SSE of the cluster is the mean, and the K-means++ initialization procedure typically results in better clustering results characterized by lower SSE.",
    "supporting_evidence_ids": [
      "E3",
      "E7"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_CLF_DT_001",
  "canonical_name": "Hunt's Algorithm",
  "definition": {
    "status": "grounded",
    "text": "Hunt's algorithm is a generic procedure for growing decision trees in a greedy",
    "supporting_evidence_ids": [
      "E1"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "text": "In Hunt's algorithm, some child nodes can be empty if no training instances possess the particular attribute values.",
    "supporting_evidence_ids": [
      "E3"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_CLU_KM_001",
  "canonical_name": "K-Means Algorithm",
  "definition": {
    "status": "grounded",
    "text": "For Euclidean data, the K-means algorithm is a special case of the EM algorithm for spherical Gaussian distributions with equal covariance matrices but different means; it can also be derived from a mixture model approach.",
    "supporting_evidence_ids": [
      "E2",
      "E6"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "abstained",
    "text": "",
    "supporting_evidence_ids": [],
    "abstention_reason": "No evidence provided in the scope_lane."
  }
}

{
  "kc_id": "KC_CLF_UND_005",
  "canonical_name": "Mutually Exclusive Classes",
  "definition": {
    "status": "grounded",
    "text": "A property of a rule set where an instance is not covered by more than one rule, preventing the prediction of conflicting classes.",
    "supporting_evidence_ids": [
      "E3"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "text": "A decision tree can be represented by a set of mutually exclusive and exhaustive rules; if a rule set is not mutually exclusive, multiple classification rules may predict conflicting classes for a single instance.",
    "supporting_evidence_ids": [
      "E1",
      "E2"
    ],
    "abstention_reason": ""
  }
}

