{
  "kc_id": "KC_CLF_DT_004",
  "canonical_name": "Gini Index",
  "definition": {
    "status": "abstained",
    "text": "",
    "supporting_evidence_ids": [],
    "abstention_reason": "The definition_lane is empty and the context_lane cannot be used to justify a grounded definition."
  },
  "scope": {
    "status": "grounded",
    "text": "In the context of finding the best split position, the Gini index can be computed in O(1) time at each candidate split position if values are kept sorted (a one-time O(N log N) operation), resulting in a complexity of O(N) to find the best split position and an overall complexity of O(N log N). The best split position is the one that produces the lowest Gini index.",
    "supporting_evidence_ids": [
      "E1",
      "E8"
    ],
    "abstention_reason": ""
  }
}

